"use client";
import { useState } from "react";
import { motion } from "framer-motion";

export default function FigmaBrandHero() {
    // State to trigger an instant re-render/replay of all animations on click
    const [animationKey, setAnimationKey] = useState(0);

    const handleReplay = () => {
        setAnimationKey((prev) => prev + 1);
    };

    return (
        <div
            key={animationKey}
            className="relative w-full max-w-4xl mx-auto flex flex-col items-center justify-center py-12 px-6 sm:px-12 bg-[#f8f9f5] dark:bg-neutral-950 bg-[linear-gradient(to_right,#e5e7eb_1px,transparent_1px),linear-gradient(to_bottom,#e5e7eb_1px,transparent_1px)] dark:bg-[linear-gradient(to_right,#262626_1px,transparent_1px),linear-gradient(to_bottom,#262626_1px,transparent_1px)] bg-[size:24px_24px] rounded-3xl overflow-hidden border border-neutral-200 dark:border-neutral-800 transition-colors duration-300 shadow-xl my-auto"
        >
            {/* Ambient Background Glow */}
            <div className="absolute w-56 h-56 bg-[#b8ff3c]/20 dark:bg-[#b8ff3c]/10 rounded-full blur-3xl pointer-events-none" />

            {/* Top Pill */}
            <motion.div
                initial={{ y: -20, opacity: 0 }}
                animate={{ y: 0, opacity: 1 }}
                transition={{ duration: 0.8, ease: [0.16, 1, 0.3, 1] }}
                className="mb-4 flex items-center gap-2 px-3.5 py-1 rounded-full border border-neutral-300 dark:border-neutral-700 bg-white/90 dark:bg-neutral-900/90 backdrop-blur-md text-[11px] font-semibold text-neutral-900 dark:text-neutral-100 shadow-xs"
            >
                <span className="w-2 h-2 rounded-full bg-[#b8ff3c] animate-pulse" />
                Websites + Branding Studio
            </motion.div>

            {/* Main Bold Stack */}
            <div className="flex flex-col items-center font-black tracking-tighter text-3xl sm:text-5xl md:text-6xl text-neutral-950 dark:text-white leading-[0.9] text-center select-none z-10">
                <motion.span
                    initial={{ y: 25, opacity: 0 }}
                    animate={{ y: 0, opacity: 1 }}
                    transition={{ duration: 0.7, delay: 0.15, ease: [0.16, 1, 0.3, 1] }}
                >
                    YOUR BRAND
                </motion.span>
                <motion.span
                    initial={{ y: 25, opacity: 0 }}
                    animate={{ y: 0, opacity: 1 }}
                    transition={{ duration: 0.7, delay: 0.25, ease: [0.16, 1, 0.3, 1] }}
                >
                    DESERVES A
                </motion.span>

                {/* Highlighted Bounding Box Row */}
                <div className="relative my-1.5 px-3 py-1">
                    <motion.div
                        initial={{ scaleX: 0 }}
                        animate={{ scaleX: 1 }}
                        transition={{ duration: 1.0, ease: [0.16, 1, 0.3, 1], delay: 0.35 }}
                        className="absolute inset-0 bg-[#c8ff29] dark:bg-[#b8ff3c] origin-left border border-neutral-900 dark:border-neutral-900 shadow-xs"
                    />

                    {/* 4 Figma-style Corner Handles */}
                    {["-top-1 -left-1", "-top-1 -right-1", "-bottom-1 -left-1", "-bottom-1 -right-1"].map(
                        (pos, i) => (
                            <motion.span
                                key={i}
                                initial={{ scale: 0 }}
                                animate={{ scale: 1 }}
                                transition={{ duration: 0.4, delay: 0.7 + i * 0.08, ease: [0.16, 1, 0.3, 1] }}
                                className={`absolute ${pos} w-2 h-2 bg-white dark:bg-neutral-900 border border-neutral-900 dark:border-neutral-100 z-20`}
                            />
                        )
                    )}
                    <span className="relative z-10 text-neutral-950">WORLD-CLASS</span>
                </div>

                <motion.span
                    initial={{ y: 25, opacity: 0 }}
                    animate={{ y: 0, opacity: 1 }}
                    transition={{ duration: 0.7, delay: 0.45, ease: [0.16, 1, 0.3, 1] }}
                >
                    DIGITAL
                </motion.span>
                <motion.span
                    initial={{ y: 25, opacity: 0 }}
                    animate={{ y: 0, opacity: 1 }}
                    transition={{ duration: 0.7, delay: 0.55, ease: [0.16, 1, 0.3, 1] }}
                >
                    PRESENCE.
                </motion.span>
            </div>

            {/* Multiplayer Cursor 1 (Top Right) */}
            <motion.div
                initial={{ opacity: 0, scale: 0.8, x: 20 }}
                animate={{
                    opacity: 1,
                    scale: 1,
                    x: [0, 8, -4, 0],
                    y: [0, -6, 3, 0]
                }}
                transition={{
                    opacity: { duration: 0.8, delay: 0.6, ease: [0.16, 1, 0.3, 1] },
                    x: { duration: 6, repeat: Infinity, ease: "easeInOut" },
                    y: { duration: 6, repeat: Infinity, ease: "easeInOut" }
                }}
                className="absolute right-4 sm:right-8 top-10 sm:top-12 z-30 flex items-center pointer-events-none scale-90 sm:scale-100"
            >
                <svg className="w-4 h-4 text-indigo-600 fill-indigo-600 drop-shadow -rotate-12" viewBox="0 0 24 24">
                    <path d="M5.653 3.125a1 1 0 0 1 1.34-1.34l14.5 9.5a1 1 0 0 1 .046 1.705l-6.046 4.031-2.915 5.83a1 1 0 0 1-1.745.18l-3.5-5.5-5.228-2.614a1 1 0 0 1-.107-1.792l14.002-9.335z" />
                </svg>
                <div className="ml-1 px-2.5 py-0.5 rounded-md rounded-tl-none bg-indigo-600 text-white text-[10px] font-bold shadow-md flex items-center gap-1 whitespace-nowrap">
                    <span>Sarah</span>
                    <span className="text-[8px] opacity-75 font-normal">Editing copy</span>
                </div>
            </motion.div>

            {/* Multiplayer Cursor 2 (Bottom Left) */}
            <motion.div
                initial={{ opacity: 0, scale: 0.8, x: -20 }}
                animate={{
                    opacity: 1,
                    scale: 1,
                    x: [0, -8, 6, 0],
                    y: [0, 8, -4, 0]
                }}
                transition={{
                    opacity: { duration: 0.8, delay: 0.7, ease: [0.16, 1, 0.3, 1] },
                    x: { duration: 7, repeat: Infinity, ease: "easeInOut", delay: 0.8 },
                    y: { duration: 7, repeat: Infinity, ease: "easeInOut", delay: 0.8 }
                }}
                className="absolute left-4 sm:left-8 bottom-10 sm:bottom-14 z-30 flex items-center pointer-events-none scale-90 sm:scale-100"
            >
                <svg className="w-4 h-4 text-emerald-500 fill-emerald-500 drop-shadow -rotate-12" viewBox="0 0 24 24">
                    <path d="M5.653 3.125a1 1 0 0 1 1.34-1.34l14.5 9.5a1 1 0 0 1 .046 1.705l-6.046 4.031-2.915 5.83a1 1 0 0 1-1.745.18l-3.5-5.5-5.228-2.614a1 1 0 0 1-.107-1.792l14.002-9.335z" />
                </svg>
                <div className="ml-1 px-2.5 py-0.5 rounded-md rounded-tl-none bg-emerald-500 text-white text-[10px] font-bold shadow-md flex items-center gap-1 whitespace-nowrap">
                    <span>Alex</span>
                    <span className="text-[8px] opacity-75 font-normal">Targeted Ads</span>
                </div>
            </motion.div>

            {/* Bottom Action Badge (Triggers Replay) */}
            <motion.div
                initial={{ y: 20, opacity: 0 }}
                animate={{ y: 0, opacity: 1 }}
                transition={{ duration: 0.7, delay: 0.65, ease: [0.16, 1, 0.3, 1] }}
                onClick={handleReplay}
                className="mt-6 px-5 py-1.5 rounded-full bg-[#c8ff29] dark:bg-[#b8ff3c] text-[10px] font-black tracking-widest uppercase text-neutral-950 shadow-sm hover:scale-105 active:scale-95 transition-all cursor-pointer select-none"
                title="Click to replay animation"
            >
                DESIGN. BUILD. GROW. ⟳
            </motion.div>
        </div>
    );
}

